lxml.html._diffcommand.split_body:
def split_body(html):
    pre = post = ''
    match = body_start_re.search(html)
    if match:
        pre = html[:match.end()]
        html = html[match.end():]
    match = body_end_re.search(html)
    if match:
        post = html[match.start():]
        html = html[:match.start()]
    return (pre, html, post)

lxml.html.html5parser.fragments_fromstri:
def fragments_fromstring(html, no_leading_text=False, guess_charset=None, parser=None):
    """Parses several HTML elements, returning a list of elements.

    The first item in the list may be a string.  If no_leading_text is true,
    then it will be an error if there is leading text, and it will always be
    a list of only elements.

    If `guess_charset` is true, the `chardet` library will perform charset
    guessing on the string.
    """
    if not isinstance(html, _strings):
        raise TypeError('string required')
    if parser is None:
        parser = html_parser
    options = {}
    if (guess_charset is None and isinstance(html, bytes)):
        guess_charset = False
    if guess_charset is not None:
        options['useChardet'] = guess_charset
    children = parser.parseFragment(html, 'div', **options)
    if (children and isinstance(children[0], _strings)):
        if no_leading_text:
            if children[0].strip():
                raise etree.ParserError('There is leading text: %r' % children[0])
            del children[0]
    return children
